   337→func (dv *RODataColumnsVerifier) SidecarDescendsFromFinalized() (err error) {
   338→	if ok, err := dv.results.cached(RequireSidecarDescendsFromFinalized); ok {
   339→		return err
   340→	}
   341→
   342→	defer dv.recordResult(RequireSidecarDescendsFromFinalized, &err)
   343→
   344→	for _, dataColumn := range dv.dataColumns {
   345→		// Extract the root of the parent block corresponding to the data column.
   346→		parentRoot := dataColumn.ParentRoot()
   347→
   348→		if !dv.fc.HasNode(parentRoot) {
   349→			return columnErrBuilder(errSidecarNotFinalizedDescendent)
